// electron-updater reads the GitHub feed generated by electron-builder.
// No GitHub credential is embedded or required on a friend's computer.
function createUpdateController({ app, updater, dialog, getWindow, notify, onState = () => {}, beforeInstall = async () => {}, schedule = setTimeout, repeat = setInterval, waitFor = deadline }) {
  let checking = false;
  let downloaded = false;
  let downloading = false;
  let lastError = null;
  let firstTimer;
  let repeatTimer;
  let startup = false;
  let startupPromise;
  let startupChecked = false;
  let stage = 'checking';
  let percent = 0;
  const publishState = () => onState({ checking, downloading, downloaded, lastError, startup, stage, percent });

  updater.autoDownload = true;
  updater.autoInstallOnAppQuit = true;
  updater.allowPrerelease = false;
  updater.allowDowngrade = false;
  // The user explicitly asks to restart; an ordinary update never restarts VAL.
  updater.on('error', (error) => { lastError = error.message; checking = false; downloading = false; publishState(); });
  updater.on('update-available', () => { downloading = true; publishState(); });
  updater.on('update-downloaded', () => {
    downloaded = true;
    downloading = false;
    lastError = null;
    publishState();
    if (!startup) notify('VAL update ready', 'It will install when you fully quit VAL. Closing to the tray keeps your call running.');
  });
  updater.on('download-progress', (progress) => {
    if (!startup) return;
    percent = Number.isFinite(progress.percent) ? Math.max(0, Math.min(100, Math.round(progress.percent))) : 0;
    publishState();
  });

  const check = async (manual = false) => {
    if (!app.isPackaged || startup || checking || downloading || downloaded) return;
    checking = true;
    lastError = null;
    publishState();
    try {
      const result = await updater.checkForUpdates();
      if (manual && result?.updateInfo?.version === app.getVersion()) {
        await dialog.showMessageBox(getWindow(), { type: 'info', message: 'VAL is up to date.', buttons: ['OK'] });
      }
    } catch (error) {
      lastError = error.message;
      if (manual) await dialog.showMessageBox(getWindow(), { type: 'info', message: 'Could not check for a VAL update.', detail: 'Try again later. The update release may not be published yet.', buttons: ['OK'] });
    } finally { checking = false; publishState(); }
  };

  return {
    prepareStartup() {
      if (!app.isPackaged) return Promise.resolve(true);
      if (startupPromise) return startupPromise;
      startup = true;
      startupPromise = (async () => {
        let result;
        for (;;) {
          try {
            if (!downloaded) {
              checking = true; stage = 'checking'; percent = 0; lastError = null; publishState();
              result = await waitFor(updater.checkForUpdates(), 15_000);
              checking = false;
              if (!result) throw new Error('Update service returned no result.');
              if (!result.isUpdateAvailable) { startupChecked = true; return true; }
              downloading = true; stage = 'downloading'; publishState();
              await waitFor(result.downloadPromise || updater.downloadUpdate(), 5 * 60_000);
              if (!downloaded) throw new Error('Update download did not complete.');
            }
            stage = 'installing'; publishState();
            await beforeInstall();
            lastError = null;
            updater.quitAndInstall(true, true);
            if (lastError) throw new Error(lastError);
            return false;
          } catch (error) {
            result?.cancellationToken?.cancel();
            lastError = error.message; checking = false; downloading = false; stage = 'error'; publishState();
            const choice = await dialog.showMessageBox(getWindow(), {
              type: 'warning', title: 'VAL update', message: 'VAL needs to finish checking and updating before opening.',
              detail: 'Check your connection and try again. Your account and conversations are preserved.',
              buttons: ['Retry', 'Quit VAL'], defaultId: 0, cancelId: 1, noLink: true
            });
            if (choice.response !== 0) { app.quit(); return false; }
          }
        }
      })().finally(() => { startup = false; checking = false; publishState(); });
      return startupPromise;
    },
    start() {
      if (!app.isPackaged) return;
      if (!startupChecked) firstTimer = schedule(() => void check(), 30_000);
      repeatTimer = repeat(() => void check(), 6 * 60 * 60 * 1000);
      firstTimer?.unref?.();
      repeatTimer.unref?.();
    },
    check,
    async installNow() {
      if (!downloaded || startup) return;
      const { response } = await dialog.showMessageBox(getWindow(), {
        type: 'question', message: 'Restart VAL to install the update?',
        detail: 'VAL will close and any active call will end. You will stay signed in.',
        buttons: ['Later', 'Restart and update'], defaultId: 0, cancelId: 0
      });
      if (response === 1) {
        try {
          await beforeInstall(); lastError = null; updater.quitAndInstall(false, true);
          if (lastError) throw new Error(lastError);
        } catch (error) {
          lastError = error.message; publishState();
          await dialog.showMessageBox(getWindow(), { type: 'warning', message: 'VAL could not install the update.', detail: 'Your current session is still open. Try the update again when you are ready.', buttons: ['OK'] });
        }
      }
    },
    stop() { clearTimeout(firstTimer); clearInterval(repeatTimer); },
    getState: () => ({ checking, downloading, downloaded, lastError })
  };
}

function deadline(task, timeoutMs) {
  let timer;
  return Promise.race([task, new Promise((_, reject) => { timer = setTimeout(() => reject(new Error('Update request timed out.')), timeoutMs); })])
    .finally(() => clearTimeout(timer));
}

module.exports = { createUpdateController };
